const STAFF_INNER = "<div class=\"m-wrap\">\n  <div class=\"m-card\">\n    <div class=\"hint\">Formal <b>Incident / Inquiry Report</b> for the client. Client must be <b>informed immediately</b> (record date &amp; time). Full incident report to client within <b>24 hours</b> of the incident. Easy entry → Save → upload photos/docs → AI suggestions → Preview → Submit.</div>\n    <div class=\"m-actions\" style=\"margin-top:10px\">\n      <button type=\"button\" class=\"m-btn m-btn-gold\" onclick=\"irNew()\">+ New incident report</button>\n      <button type=\"button\" class=\"m-btn m-btn-navy\" onclick=\"irLoad()\">\ud83d\udd04 Refresh list</button>\n      <button type=\"button\" class=\"m-btn m-btn-grey\" onclick=\"irSendTestDraft()\">\ud83d\udce8 Send test draft to Director</button>\n    </div>\n    <div id=\"irMsg\" class=\"hint\" style=\"margin-top:8px\"></div>\n  </div>\n  <div class=\"m-card\">\n    <h4 style=\"color:#fde68a;margin:0 0 10px\">Saved reports</h4>\n    <div class=\"mtblwrap\"><table class=\"mtbl\"><thead><tr><th>REF</th><th>Date</th><th>Client / Place</th><th>Type</th><th>Files</th><th>Close deadline</th><th>Status</th><th></th></tr></thead><tbody id=\"irRows\"></tbody></table></div>\n  </div>\n  <div id=\"irFormCard\" class=\"m-card hidden\">\n    <h4 style=\"color:#fde68a;margin:0 0 6px\" id=\"irFormTitle\">New incident report</h4>\n    <p class=\"hint\" style=\"margin:0 0 12px\">Fill the letter fields. Upload up to <b>5 photos</b> and <b>5 evidence documents</b> (replacement proof, deployment order, letters). Tap <b>Suggest how to avoid recurrence</b> for AI ideas. Submit sends the letter + files to the client.</p>\n    <input type=\"hidden\" id=\"ir_id\">\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px\">\n      <div><label class=\"m-lbl\">Report dated</label><input class=\"m-inp\" type=\"date\" id=\"ir_reportDate\"></div>\n      <div style=\"grid-column:1/-1;padding:12px;border:1px solid #334155;border-radius:10px;background:#0e1730\">\n        <b style=\"color:#fde68a\">Date &amp; time of incident *</b>\n        <p class=\"hint\" style=\"margin:6px 0 8px\">When the incident happened.</p>\n        <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;align-items:end\">\n          <div><label class=\"m-lbl\">Date</label><input class=\"m-inp\" type=\"date\" id=\"ir_incidentDate\"></div>\n          <div><label class=\"m-lbl\">Time of incident</label><input class=\"m-inp\" type=\"time\" id=\"ir_incidentTime\"></div>\n          <div><button type=\"button\" class=\"m-btn m-btn-grey\" onclick=\"irStampIncidentNow()\">Use now</button></div>\n        </div>\n      </div>\n      <div style=\"grid-column:1/-1;padding:12px;border:1px solid #c9a84c;border-radius:10px;background:#1a2338\">\n        <b style=\"color:#fde68a\">Informed to client *</b>\n        <p class=\"hint\" style=\"margin:6px 0 8px\">Record when the client was told — should be <b>immediately</b> after the incident.</p>\n        <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;align-items:end\">\n          <div><label class=\"m-lbl\">Date</label><input class=\"m-inp\" type=\"date\" id=\"ir_informedDate\"></div>\n          <div><label class=\"m-lbl\">Time</label><input class=\"m-inp\" type=\"time\" id=\"ir_informedTime\"></div>\n          <div><button type=\"button\" class=\"m-btn m-btn-gold\" onclick=\"irStampInformedNow()\">Informed now</button></div>\n        </div>\n      </div>\n      <div><label class=\"m-lbl\">Client / Site</label><select class=\"m-inp\" id=\"ir_client\" onchange=\"irOnClient()\"></select></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Place of Incident</label><input class=\"m-inp\" id=\"ir_place\" placeholder=\"e.g. HDFC Branch Ameerpet\"></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Type of incident *</label><input class=\"m-inp\" id=\"ir_type\" placeholder=\"Short title of what happened\"></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Loss of Property &amp; approximate cost</label><input class=\"m-inp\" id=\"ir_loss\" value=\"Nil\"></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Sources of Information received</label><input class=\"m-inp\" id=\"ir_source\" placeholder=\"Who informed you\"></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Personnel involved in incident</label><input class=\"m-inp\" id=\"ir_personnel\" placeholder=\"ID No., designation, name\"></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Name of Inquiry Officer/Manager</label><input class=\"m-inp\" id=\"ir_officer\"></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Brief description of the incident/Inquiry *</label><textarea class=\"m-inp\" id=\"ir_brief\" rows=\"4\" style=\"min-height:90px\"></textarea></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Suspected persons if any</label><input class=\"m-inp\" id=\"ir_suspect\"></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Findings</label><textarea class=\"m-inp\" id=\"ir_findings\" rows=\"4\" style=\"min-height:90px\"></textarea></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Action Taken *</label><textarea class=\"m-inp\" id=\"ir_action\" rows=\"4\" style=\"min-height:90px\"></textarea></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Suggestion (Branch / Inquiry Officer \u2014 human)</label>\n        <textarea class=\"m-inp\" id=\"ir_suggest\" rows=\"4\" style=\"min-height:90px\" placeholder=\"Write your branch suggestion first\"></textarea>\n      </div>\n      <div style=\"grid-column:1/-1;padding:12px;border:1px solid #c9a84c;border-radius:10px;background:#1a2338\">\n        <label class=\"m-lbl\" style=\"color:#fde68a\">Alerts &amp; suggestions (system \u2014 after human reporting)</label>\n        <div style=\"margin:6px 0 8px\"><button type=\"button\" class=\"m-btn m-btn-navy\" id=\"irBtnSuggest\" onclick=\"irSuggest()\">\u2728 Generate alerts &amp; suggestions</button></div>\n        <textarea class=\"m-inp\" id=\"ir_aiSuggest\" rows=\"5\" style=\"min-height:110px\" placeholder=\"System alerts appear here after your human suggestion \u2014 review before submit\"></textarea>\n      </div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Enclosure note (optional)</label><input class=\"m-inp\" id=\"ir_photos\" placeholder=\"e.g. Photos of the replacement FA / deployment order are attached.\"></div>\n      <div style=\"grid-column:1/-1;padding:12px;border:1px solid #334155;border-radius:10px;background:#0e1730\">\n        <b style=\"color:#fde68a\">Photos (up to 5)</b>\n        <p class=\"hint\" style=\"margin:6px 0 8px\">Site photos, replacement FA photo, ID card, etc.</p>\n        <input type=\"file\" id=\"ir_photoFile\" accept=\"image/*\" multiple class=\"m-inp\" onchange=\"irPickPhotos(this)\">\n        <div id=\"irPhotoList\" class=\"hint\" style=\"margin-top:8px\"></div>\n      </div>\n      <div style=\"grid-column:1/-1;padding:12px;border:1px solid #334155;border-radius:10px;background:#0e1730\">\n        <b style=\"color:#fde68a\">Evidence documents (up to 5)</b>\n        <p class=\"hint\" style=\"margin:6px 0 8px\">Written letters, proof of changing the guard, Deployment Order copy, etc. (PDF / photo / Word).</p>\n        <div style=\"display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;margin-bottom:8px\">\n          <div style=\"flex:1;min-width:160px\"><label class=\"m-lbl\">Label</label><input class=\"m-inp\" id=\"ir_evLabel\" placeholder=\"e.g. Deployment order copy\"></div>\n          <div style=\"flex:1;min-width:180px\"><label class=\"m-lbl\">File</label><input type=\"file\" id=\"ir_evFile\" accept=\"image/*,.pdf,.doc,.docx,application/pdf\" class=\"m-inp\" onchange=\"irPickEvidence(this)\"></div>\n        </div>\n        <div id=\"irEvList\" class=\"hint\"></div>\n      </div>\n      <div><label class=\"m-lbl\">Signatory name</label><input class=\"m-inp\" id=\"ir_signName\"></div>\n      <div><label class=\"m-lbl\">Designation</label><input class=\"m-inp\" id=\"ir_signDesig\"></div>\n      <div><label class=\"m-lbl\">Your email (CC on send)</label><input class=\"m-inp\" id=\"ir_signEmail\" type=\"email\"></div>\n      <div style=\"grid-column:1/-1\"><label class=\"m-lbl\">Client email (To) \u2014 needed for Submit</label><input class=\"m-inp\" id=\"ir_clientEmail\" type=\"email\" placeholder=\"client@example.com\"></div>\n    </div>\n    <div class=\"m-actions\" style=\"margin-top:14px\">\n      <button type=\"button\" class=\"m-btn m-btn-green\" id=\"irBtnSave\" onclick=\"irSave()\">\ud83d\udcbe Save</button>\n      <button type=\"button\" class=\"m-btn m-btn-navy\" onclick=\"irPreview()\">\ud83d\udc41 Preview letter</button>\n      <button type=\"button\" class=\"m-btn m-btn-gold\" id=\"irBtnSubmit\" onclick=\"irSubmit()\">\ud83d\udce8 Submit to client</button>\n      <button type=\"button\" class=\"m-btn m-btn-grey\" onclick=\"irCloseForm()\">Close form</button>\n    </div>\n    <div id=\"irFormMsg\" class=\"hint\" style=\"margin-top:8px\"></div>\n  </div>\n  <div id=\"irPreviewModal\" style=\"display:none;position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:9999;align-items:center;justify-content:center;padding:12px\">\n    <div class=\"m-card\" style=\"max-width:860px;width:100%;max-height:92vh;overflow:auto;background:#fff;color:#0f172a\">\n      <div style=\"display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:10px\">\n        <b style=\"color:#14224f\">Letter preview</b>\n        <button type=\"button\" class=\"m-btn m-btn-navy\" onclick=\"irClosePreview()\">Close</button>\n      </div>\n      <iframe id=\"irPreviewFrame\" title=\"Letter preview\" sandbox=\"allow-same-origin\" style=\"display:block;width:100%;min-height:70vh;height:70vh;border:0;background:#f1f5f9;border-radius:8px\"></iframe>\n    </div>\n  </div>\n</div>";

